  5925	md_is_container_mark(MD_CTX* ctx, unsigned indent, OFF beg, OFF* p_end, MD_CONTAINER* p_container)
  5926	{
  5927	    OFF off = beg;
  5928	    OFF max_end;
  5929	
  5930	    if(off >= ctx->size  ||  indent >= ctx->code_indent_offset)
  5931	        return FALSE;
  5932	
  5933	    /* Check for block quote mark. */
  5934	    if(CH(off) == _T('>')) {
  5935	        off++;
  5936	        p_container->ch = _T('>');
  5937	        p_container->is_loose = FALSE;
  5938	        p_container->is_task = FALSE;
  5939	        p_container->mark_indent = indent;
  5940	        p_container->contents_indent = indent + 1;
  5941	        *p_end = off;
  5942	        return TRUE;
  5943	    }
  5944	
  5945	    /* Check for list item bullet mark. */
  5946	    if(ISANYOF(off, _T("-+*"))  &&  (off+1 >= ctx->size || ISBLANK(off+1) || ISNEWLINE(off+1))) {
  5947	        p_container->ch = CH(off);
  5948	        p_container->is_loose = FALSE;
  5949	        p_container->is_task = FALSE;
  5950	        p_container->mark_indent = indent;
  5951	        p_container->contents_indent = indent + 1;
  5952	        *p_end = off+1;
  5953	        return TRUE;
  5954	    }
  5955	
  5956	    /* Check for ordered list item marks. */
  5957	    max_end = off + 9;
  5958	    if(max_end > ctx->size)
  5959	        max_end = ctx->size;
  5960	    p_container->start = 0;
  5961	    while(off < max_end  &&  ISDIGIT(off)) {
  5962	        p_container->start = p_container->start * 10 + CH(off) - _T('0');
  5963	        off++;
  5964	    }
  5965	    if(off > beg  &&
  5966	       off < ctx->size  &&
  5967	       (CH(off) == _T('.') || CH(off) == _T(')'))  &&
  5968	       (off+1 >= ctx->size || ISBLANK(off+1) || ISNEWLINE(off+1)))
  5969	    {
  5970	        p_container->ch = CH(off);
  5971	        p_container->is_loose = FALSE;
  5972	        p_container->is_task = FALSE;
  5973	        p_container->mark_indent = indent;
  5974	        p_container->contents_indent = indent + off - beg + 1;
  5975	        *p_end = off+1;
  5976	        return TRUE;
  5977	    }
  5978	
  5979	    return FALSE;
  5980	}
